if name == "oa":
    if keys == {"op", "cid", "flow", "c", "s", "key", "now"}:
        # 旧键集：等价于三项成本均为 1。
        bc = cc = sc = 1
    elif keys == {"op", "cid", "flow", "c", "s", "key", "bc", "cc", "sc", "now"}:
