if name == "bp":
    if keys != {"op", "low", "high"}:
        fail(EXIT_INPUT, "INPUT")
    low = parse_bp_num(raw_op["low"])
    high = parse_bp_num(raw_op["high"])
    # 阈值关系 low < high 在解析期即校验（high ≤ os.q 留执行期）。
    if not low < high:
        fail(EXIT_INPUT, "INPUT")
    return ("bp", low, high)

if name == "bq":
    if keys != {"op"}:
        fail(EXIT_INPUT, "INPUT")
    return ("bq",)

if name == "qp":
    # 队列出队策略：精确键序 op,mode（键须按此序出现）；mode 仅 F/S，
    # 键序、类型或值非法报 INPUT。
    if list(raw_op) != ["op", "mode"]:
        fail(EXIT_INPUT, "INPUT")
    mode = raw_op["mode"]
    if not isinstance(mode, str) or mode not in ("F", "S"):
        fail(EXIT_INPUT, "INPUT")
    return ("qp", mode)

if name == "rp":
    # FIFO 满载策略：精确键序 op,mode（键须按此序出现）；mode 仅 T/H
    # （T 尾拒绝、H 头淘汰），键序、类型或值非法报 INPUT。
    if list(raw_op) != ["op", "mode"]:
        fail(EXIT_INPUT, "INPUT")
    mode = raw_op["mode"]
    if not isinstance(mode, str) or mode not in ("T", "H"):
        fail(EXIT_INPUT, "INPUT")
    return ("rp", mode)

if name == "rg":
