def parse_cost(value):
    # 令牌成本 bc/cc/sc ∈ [0, 10^9]，非 bool 整数。
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or not 0 <= value <= 10 ** 9
    ):
        fail(EXIT_INPUT, "INPUT")
    return value


def parse_quota_limit(value):
    # 固定窗口配额上限 limit ∈ [1, 10^18]，非 bool 整数。
    if (
